<section class="page-heading">
    <div><div class="eyebrow">Published data only</div><h1>Reports</h1><p>Measure published price movement across commodities, markets, and date ranges.</p></div>
    <div class="heading-actions"><button class="button button-secondary" type="button" id="print-report"><i class="fa-solid fa-print"></i><span>Print / PDF</span></button><button class="button button-primary" type="button" id="export-report"><i class="fa-solid fa-file-arrow-down"></i><span>Export CSV</span></button></div>
</section>
<section class="panel">
    <div class="filters"><div class="filter-control"><label for="report-commodity">Commodity</label><select id="report-commodity"><option value="">All commodities</option></select></div><div class="filter-control"><label for="report-market">Market</label><select id="report-market"><option value="">All markets</option></select></div><div class="filter-control"><label for="report-from">From</label><input id="report-from" type="date"></div><div class="filter-control"><label for="report-to">To</label><input id="report-to" type="date"></div><div class="filter-actions"><button class="button button-primary" type="button" id="run-report"><i class="fa-solid fa-chart-line"></i><span>Run report</span></button></div></div>
    <div class="panel-body" id="report-summary"><div class="report-metrics"><div class="metric-card"><span>Records</span><strong>—</strong></div><div class="metric-card"><span>Average price</span><strong>—</strong></div><div class="metric-card"><span>Highest price</span><strong>—</strong></div><div class="metric-card"><span>Lowest price</span><strong>—</strong></div><div class="metric-card"><span>Change</span><strong>—</strong></div></div><div class="table-wrap"><table class="data-table"><caption class="visually-hidden">Published price records for the selected filters</caption><thead><tr><th scope="col">Commodity</th><th scope="col">Market</th><th scope="col">Date</th><th scope="col">Price</th><th scope="col">Source</th><th scope="col">Approved by</th></tr></thead><tbody id="report-table"><tr><td colspan="6" class="table-empty"><i class="fa-solid fa-chart-column"></i><span>Run a report to see published records.</span></td></tr></tbody></table></div></div>
</section>
